insert into bitd.character_playbooks(name,defaults,rules) values ('Ghost/Echo','{"alias": "", "playerName": "", "look": "", "wearing": "", "heritage": "", "heritageDetails": "", "background": "", "backgroundDetails": "", "vice": "", "viceHookup": "", "notes": "", "abilityNotes": "", "advancementNotes": "", "equipmentNotes": "", "actions": {"hunt": 1, "study": 0, "survey": 0, "tinker": 0, "finesse": 0, "prowl": 1, "skirmish": 0, "wreck": 0, "attune": 1, "command": 0, "consort": 0, "sway": 0}, "abilities": ["Resonance Echo"], "echoPet": [], "versatile": [], "relationships": [], "loadout": {"mode": "Quiet", "carriedStacks": 0}, "armor": {"kind": "none", "worn": false, "totaled": false, "source": "", "notes": ""}, "wealth": {"stacks": 0, "bank": 0}, "xp": {"playbook": 0, "insight": 0, "prowess": 0, "resolve": 0}, "resources": [], "equipment": [], "stress": 0, "stressCapacity": 9, "keys": [], "deadlocks": [], "harm": {"passing": ["", ""], "major": ["", ""], "critical": [""], "mortal": [""]}, "healing": {"progress": 0, "permanent": 0}, "ghost": {"retainedEcho": [], "transformation": "", "needNotes": "", "operations": ""}}'::jsonb,'{"abilities": ["Resonance Echo", "Dissipate", "Manifest", "Poltergeist", "Possess", "Versatile"], "quiet": 3, "loud": 6, "wallet": 4, "bank": 40, "playbookXp": 8, "attributeXp": 6, "builtInArmor": false, "actionMax": 4, "harmSlots": {"passing": 2, "major": 2, "critical": 1, "mortal": 1}, "source": "Blades ’68 playbooks v6 page 9; book v1.0.1 pp.334–340", "creation": "Hunt 1, Prowl 1, Attune 1. On transformation add previous ratings, maximum 4. Remove Deadlocks, retain only Echo special abilities, and record iconic items in ghost form and enemies/rivals.", "xpTrigger": "vengeance, outrage or anger", "abilityGuidance": "Resonance Echo is fixed. Do not choose Possess as a starting trait. Dissipate costs 1 Drain plus features; Manifest costs 1; Poltergeist costs 1 plus magnitude. Retain named, source-tagged Echo abilities deliberately. Transformation is a table decision; no automatic conversion.", "conditionKind": "ghost", "fixedAbilities": ["Resonance Echo"], "abilityChoiceGuidance": "Resonance Echo is preselected. Choose one more trait at creation; Possess requires a later advance.", "resourceGuidance": "Drain 9; no turning Keys. At full Drain replace a Key with an echo irregularity. Possess a living victim and consume resonance energy to clear half Drain, rounded down; Possess must first be earned."}'::jsonb);
