create table bitd.paranormal_playbook_availability (
 campaign_id uuid not null references bitd.campaigns on delete cascade,
 playbook text not null references bitd.character_playbooks(name),
 enabled boolean not null default false,
 primary key(campaign_id,playbook),
 check (playbook in ('Ghost/Echo','Vampire','Time Traveler from the Future','Time Traveler from the Past'))
);
alter table bitd.paranormal_playbook_availability enable row level security;
revoke all on bitd.paranormal_playbook_availability from public,anon,authenticated;
create function bitd.get_campaign_playbooks(p_campaign uuid) returns table(name text,paranormal boolean,enabled boolean)
language plpgsql security definer set search_path='' as $$
begin
 if bitd.campaign_role(p_campaign) is null then raise exception 'Campaign membership required' using errcode='42501'; end if;
 return query select p.name,p.name in ('Ghost/Echo','Vampire','Time Traveler from the Future','Time Traveler from the Past'),case when p.name in ('Ghost/Echo','Vampire','Time Traveler from the Future','Time Traveler from the Past') then coalesce(a.enabled,false) else true end from bitd.character_playbooks p left join bitd.paranormal_playbook_availability a on a.playbook=p.name and a.campaign_id=p_campaign order by p.name;
end $$;
create function bitd.set_paranormal_playbook(p_campaign uuid,p_playbook text,p_enabled boolean) returns void
language plpgsql security definer set search_path='' as $$
begin
 if bitd.campaign_role(p_campaign) is distinct from 'gm' then raise exception 'Current campaign GM required' using errcode='42501'; end if;
 if p_enabled is null or p_playbook is null or p_playbook not in ('Ghost/Echo','Vampire','Time Traveler from the Future','Time Traveler from the Past') then raise exception 'Choose a published paranormal playbook'; end if;
 perform 1 from bitd.campaigns where id=p_campaign for update;
 insert into bitd.paranormal_playbook_availability(campaign_id,playbook,enabled) values(p_campaign,p_playbook,p_enabled) on conflict(campaign_id,playbook) do update set enabled=excluded.enabled;
end $$;
-- Serialize creation with availability changes while preserving the single public create signature.
create function bitd.check_paranormal_creation() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if bitd.campaign_role(new.campaign_id) is null then raise exception 'Current campaign membership required' using errcode='42501'; end if;
 perform 1 from bitd.campaigns where id=new.campaign_id for share;
 if new.data->>'playbook' in ('Ghost/Echo','Vampire','Time Traveler from the Future','Time Traveler from the Past') and not exists(select 1 from bitd.paranormal_playbook_availability where campaign_id=new.campaign_id and playbook=new.data->>'playbook' and enabled) then raise exception 'This paranormal playbook is not currently enabled by the campaign GM'; end if;
 return new;
end $$;
create trigger character_000_paranormal_availability before insert on bitd.characters for each row execute function bitd.check_paranormal_creation();
revoke all on function bitd.get_campaign_playbooks(uuid),bitd.set_paranormal_playbook(uuid,text,boolean),bitd.check_paranormal_creation() from public,anon,authenticated;
grant execute on function bitd.get_campaign_playbooks(uuid),bitd.set_paranormal_playbook(uuid,text,boolean) to authenticated;

-- Own patch contribution; the public patch RPC already merges validated objects one level.
alter function bitd.validate_character_patch(jsonb) rename to validate_character_pre_paranormal_patch;
create function bitd.paranormal_source_present(p_value text) returns boolean language sql immutable set search_path='' as $$
 select coalesce(p_value,'') ~ U&'[^\0009-\000D\0020\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]'
$$;
create function bitd.validate_paranormal_ability_records(p_value jsonb,p_echo boolean) returns void language plpgsql set search_path='' as $$
declare item jsonb; e record;
begin
 if jsonb_typeof(p_value)<>'array' or jsonb_array_length(p_value)>100 then raise exception 'Expected sourced ability records'; end if;
 for item in select * from jsonb_array_elements(p_value) loop
  if jsonb_typeof(item)<>'object' or not item ?& array['name','source','notes'] or (not p_echo and not item ? 'trait') then raise exception 'Record ability name, source, notes and paired advancement trait'; end if;
  for e in select * from jsonb_each(item) loop
   if (e.key not in ('name','source','notes') and not (not p_echo and e.key='trait')) or jsonb_typeof(e.value)<>'string' or length(e.value #>> '{}')>12000 then raise exception 'Invalid sourced ability'; end if;
  end loop;
  if not bitd.paranormal_source_present(item->>'name') or not bitd.paranormal_source_present(item->>'source') then raise exception 'Ability name and source are required'; end if;
  if p_echo and (item->>'name') not in ('Echo Pet','Echo Walker','Echo Fighter','Echo Projection','Echo Twin','Echo Chamber') then raise exception 'Only retained Echo special abilities belong here'; end if;
  if not p_echo and exists(select 1 from bitd.character_playbooks p where p.name in ('Hull','Ghost/Echo','Vampire','Time Traveler from the Future','Time Traveler from the Past') and p.rules->'abilities' ? (item->>'name') and item->>'name'<>'Versatile') then raise exception 'Paranormal and Hull traits are native to their playbooks'; end if;
 end loop;
end $$;
create function bitd.validate_character_paranormal_patch(p_patch jsonb) returns void language plpgsql set search_path='' as $$
declare k text; e record; item jsonb; n record;
begin
 foreach k in array array['ghost','vampire','traveler'] loop
  if not p_patch ? k then continue; end if;
  if jsonb_typeof(p_patch->k)<>'object' then raise exception 'Expected paranormal record'; end if;
  for e in select * from jsonb_each(p_patch->k) loop
   if (k in ('ghost','vampire') and e.key='retainedEcho') or (k='traveler' and e.key='gainedAbilities') then
    perform bitd.validate_paranormal_ability_records(e.value,k<>'traveler');
   elsif (k='ghost' and e.key in ('transformation','needNotes','operations')) or (k='vampire' and e.key in ('transformation','feeding','operations')) or (k='traveler' and e.key in ('origin','operations','itemDecisions')) then
    if jsonb_typeof(e.value)<>'string' or length(e.value #>> '{}')>12000 then raise exception 'Invalid paranormal text'; end if;
   elsif k='vampire' and e.key in ('darkMajesty','sinisterGuile') then
    if jsonb_typeof(e.value)<>'string' or (e.key='darkMajesty' and (e.value #>> '{}') not in ('','Insight','Prowess','Resolve')) or (e.key='sinisterGuile' and (e.value #>> '{}') not in ('','Additional activity','+1d downtime rolls')) then raise exception 'Invalid vampiric choice'; end if;
   elsif k='vampire' and e.key='strictures' then
    if jsonb_typeof(e.value)<>'array' or jsonb_array_length(e.value)>6 then raise exception 'Invalid strictures'; end if;
    for item in select * from jsonb_array_elements(e.value) loop
     if jsonb_typeof(item)<>'string' or (item #>> '{}') not in ('Dayfire','Slumber','Forbidden','Repelled','Bestial','Bound') then raise exception 'Unknown stricture'; end if;
    end loop;
    if (select count(*)<>count(distinct value) from jsonb_array_elements(e.value)) then raise exception 'Duplicate stricture'; end if;
   elsif k='vampire' and e.key='darkServants' then
    if jsonb_typeof(e.value)<>'array' or jsonb_array_length(e.value)<>2 then raise exception 'Record two Dark Servants'; end if;
    for item in select * from jsonb_array_elements(e.value) loop
     if jsonb_typeof(item)<>'object' or not item ?& array['name','relationship','notes'] then raise exception 'Incomplete Dark Servant'; end if;
     for n in select * from jsonb_each(item) loop
      if n.key not in ('name','relationship','notes') or jsonb_typeof(n.value)<>'string' or length(n.value #>> '{}')>12000 then raise exception 'Invalid Dark Servant'; end if;
     end loop;
    end loop;
   elsif k='traveler' and e.key='alluvium' then
    if not bitd.character_record_integer(e.value,8) then raise exception 'Alluvium capacity is eight'; end if;
   elsif k='traveler' and e.key='mission' then
    if jsonb_typeof(e.value)<>'string' or (e.value #>> '{}') not in ('','Prevent a Terrible Future','Chase Down Something Bad','Find a Solution and Take It Back','Save the Present from a Past Mistake') then raise exception 'Unknown temporal mission'; end if;
   elsif k='traveler' and e.key='details' then
    if jsonb_typeof(e.value)<>'array' or jsonb_array_length(e.value)<>4 then raise exception 'Record four mission details'; end if;
    for item in select * from jsonb_array_elements(e.value) loop
     if jsonb_typeof(item)<>'object' or not item ?& array['revealed','text'] then raise exception 'Incomplete mission detail'; end if;
     for n in select * from jsonb_each(item) loop
      if n.key='revealed' then
       if jsonb_typeof(n.value)<>'boolean' then raise exception 'Invalid mission reveal'; end if;
      elsif n.key='text' then
       if jsonb_typeof(n.value)<>'string' or length(n.value #>> '{}')>12000 then raise exception 'Invalid mission detail text'; end if;
      else raise exception 'Unknown mission detail field'; end if;
     end loop;
    end loop;
   else raise exception 'Unknown % field: %',k,e.key; end if;
  end loop;
 end loop;
end $$;
create function bitd.validate_character_patch(p_patch jsonb) returns void language plpgsql set search_path='' as $$
begin
 perform bitd.validate_character_pre_paranormal_patch(p_patch-array['ghost','vampire','traveler']);
 perform bitd.validate_character_paranormal_patch(p_patch);
end $$;
create function bitd.check_character_paranormal_state() returns trigger language plpgsql set search_path='' as $$
declare book text:=new.data->>'playbook'; k text; item jsonb; e record; attr text; allowed integer;
begin
 perform bitd.validate_character_paranormal_patch(new.data);
 foreach k in array array['ghost','vampire','traveler'] loop
  if new.data ? k and not ((k='ghost' and book='Ghost/Echo') or (k='vampire' and book='Vampire') or (k='traveler' and book in ('Time Traveler from the Future','Time Traveler from the Past'))) then raise exception 'Paranormal records require the matching saved playbook'; end if;
 end loop;
 -- Living characters cannot acquire paranormal traits through Versatile.
 for item in select * from jsonb_array_elements(new.data->'versatile') loop
  if exists(select 1 from bitd.character_playbooks p where p.name in ('Ghost/Echo','Vampire','Time Traveler from the Future','Time Traveler from the Past') and p.rules->'abilities' ? (item->>'name') and item->>'name'<>'Versatile') then raise exception 'Paranormal traits cannot be taken through Versatile'; end if;
 end loop;
 -- Hull memories also grant another-playbook special abilities, never native paranormal traits.
 for item in select * from jsonb_array_elements(new.data->'hull'->'memories') loop
  if exists(select 1 from bitd.character_playbooks p where p.name in ('Ghost/Echo','Vampire','Time Traveler from the Future','Time Traveler from the Past') and p.rules->'abilities' ? (item->>'ability') and item->>'ability'<>'Versatile') then raise exception 'Paranormal traits are not memory-granted special abilities'; end if;
 end loop;
 if book='Ghost/Echo' then
  if not new.data ? 'ghost' or not new.data->'abilities' ? 'Resonance Echo' then raise exception 'Ghost/Echo retains Resonance Echo and its records'; end if;
  if (new.data->>'stressCapacity')::integer<>9 then raise exception 'Ghost Drain capacity is nine'; end if;
  for item in select * from jsonb_array_elements(new.data->'deadlocks') loop
   if item->>'name' not in ('Chaotic','Destructive','Furious','Obsessive','Territorial','Sadistic') then raise exception 'Choose an echo irregularity'; end if;
  end loop;
 elsif book='Vampire' then
  if not new.data ? 'vampire' or not new.data->'abilities' ? 'Vampire' then raise exception 'Vampire retains its native trait and records'; end if;
  if (new.data->>'stressCapacity')::integer<>12 or jsonb_array_length(new.data->'deadlocks')<>4 or jsonb_array_length(new.data->'keys')<>0 then raise exception 'Vampires have twelve Stress and four filled Deadlocks'; end if;
  if not new.data->'vampire'->'strictures' ? 'Dayfire' then raise exception 'Vampires retain Dayfire'; end if;
  attr:=new.data->'vampire'->>'darkMajesty';
  if attr<>'' and not new.data->'abilities' ? 'Dark Majesty' then raise exception 'Attribute choice requires Dark Majesty'; end if;
  if new.data->'vampire'->>'sinisterGuile'<>'' and not new.data->'abilities' ? 'Sinister Guile' then raise exception 'Downtime choice requires Sinister Guile'; end if;
  for e in select * from jsonb_each(new.data->'actions') loop
   allowed:=case when (attr='Insight' and e.key in ('hunt','study','survey','tinker')) or (attr='Prowess' and e.key in ('finesse','prowl','skirmish','wreck')) or (attr='Resolve' and e.key in ('attune','command','consort','sway')) then 5 else 4 end;
   if (e.value #>> '{}')::integer>allowed then raise exception 'Rating five requires Dark Majesty in that attribute'; end if;
  end loop;
 elsif book in ('Time Traveler from the Future','Time Traveler from the Past') then
  if not new.data ? 'traveler' or not new.data->'abilities' ? (case when book='Time Traveler from the Future' then 'Future Shock' else 'Haunted by the Past' end) then raise exception 'Time Traveler retains its starting trait and records'; end if;
  if (new.data->>'stressCapacity')::integer<>9 then raise exception 'Instability capacity is nine'; end if;
  for item in select * from jsonb_array_elements(new.data->'traveler'->'gainedAbilities') loop
   if not (new.data->'abilities') ? (item->>'trait') or (new.data->'sheet'->'fixedAbilities') ? (item->>'trait') then raise exception 'Gained ability requires its selected nonfixed native advancement trait'; end if;
   if book='Time Traveler from the Future' and not exists(select 1 from bitd.character_playbooks p where p.name in ('Hound','Intellectual','Operative','Paranormalist','Radical','Swinger','Veteran') and p.rules->'abilities' ? (item->>'name')) then raise exception 'Future Shock ability must come from a published human playbook'; end if;
  end loop;
  k:=new.data->'traveler'->>'mission';
  if k<>'' and ((book='Time Traveler from the Future' and k not in ('Prevent a Terrible Future','Chase Down Something Bad')) or (book='Time Traveler from the Past' and k not in ('Find a Solution and Take It Back','Save the Present from a Past Mistake'))) then raise exception 'Choose a mission for this era'; end if;
  for item in select * from jsonb_array_elements(new.data->'deadlocks') loop
   if item->>'name' not in ('Body Phasing','Hallucinations','Lagging','Headaches','Flashbacks','Time Skips') then raise exception 'Choose a temporal glitch'; end if;
  end loop;
 end if;
 return new;
end $$;
create trigger character_paranormal_check before insert or update on bitd.characters for each row execute function bitd.check_character_paranormal_state();
revoke all on function bitd.validate_character_pre_paranormal_patch(jsonb),bitd.paranormal_source_present(text),bitd.validate_paranormal_ability_records(jsonb,boolean),bitd.validate_character_paranormal_patch(jsonb),bitd.validate_character_patch(jsonb),bitd.check_character_paranormal_state() from public,anon,authenticated;
